"""Second fixed six-team development sample; IDs/seed only, before outcomes."""
from pathlib import Path
import hashlib,json,random,subprocess
from injury_warning.pilot_io import ROOT
D=ROOT/'phase2c';SEED=20240219

def draw(frame):
    ordered=sorted(frame,key=lambda r:int(r['team_id']))
    return sorted(random.Random(SEED).sample(ordered,6),key=lambda r:int(r['team_id']))

def register():
    prior=json.loads((ROOT/'phase2a/registration/sample_v1.json').read_text());excluded={'1610612738'}|{r['team_id'] for r in prior['selected']};frame=[r for r in prior['frame'] if r['team_id'] not in excluded];assert len(frame)==23
    checkpoint=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip()
