    spec=dict(version='phase2c_frozen_collection_v1',checkpoint_commit=checkpoint,phase2b_amendment_commits=['acac9e43fc409e255c1353465f1a44ac965bb020','59a0b38a9a42bebaaae8121c81895662340832a6','7e4c6b8ea76e43fc694e29199fd298af7b62f12b'],implementation_sha256=code,reuse='Parameter-bind existing Phase2A acquisition/parser and Phase2B clocks, knowledge, sequences, segments and build; no copied parallel implementation. Isolated Phase2C outputs; shared checksummed cache.',frozen_registrations=['phase1c/registration/amendment_v1.json','phase1d/registration/alternative_v1.json','phase2b/registration/amendment_v1.json','phase2b/registration/clock_source_clarification_v1.json','phase2b/registration/schedule_bound_clarification_v1.json'],endpoint='new documented injury-related absence run begins in (decision, decision+14 elapsed days], later >=10 consecutive actual applicable-team injury misses, supported common episode; ambiguous original anchor retained',timing='next-day noon America/New_York and one additional local calendar day',history='28 elapsed day workloads; acquired cumulative injury history separately from trailing28-day recent evidence and game-specific status; all other registered features/thresholds unchanged',publication='A verified original historical publication; B final stats/full recap end-upper+6h, report header+30min, qualifying dated metadata+60min where applicable; new retrospective review evidence C only. No A verified by assumption.',evidence='No retrospective C evidence enters prospective eligibility/features. Event-specific C linkage describes positive strata only. Missing searched signals never prove health.',dates=dict(index_start='2024-01-01',index_end='2024-02-18',history_start='2023-12-04',onset_extension_end='2024-03-03',followup_end='2024-04-14'),collection='Exactly six additional prediction teams; all rosters, complete game pages/books/recaps; report daily probes and executed dated searches; targeted prior/destination team evidence for actual members only; complete full batch independent of events. Resumable; no retry/bypass recorded denials or paid services.',membership='Review trade/waiver/ten-day boundaries before final build. Explicit dated sources, observed roster spans and actual schedules; unverified gaps remain unknown, never zero workload/injury.',review='Every positive and potentially qualifying unknown event; maximal consecutive injury segments, common identity from total sources not diagnosis alone. Seed20240219 negative sample >=5/team/lag where available; human packet accept/amend/reject unanswered, no claim independent human review.',cumulative='Canonical player/game/lag decisions, event IDs and actual source IDs; report new six, first six audited2B, Boston separately and union; disclose cross-batch transfer/event overlap and time-dependent evidence differences.',prohibited='No models, preprocessing fitting, threshold tuning, protected seasons/holdouts, optional stopping or league-wide injury rates. Genuine new bug gets versioned evidence/test/impact disclosure.',prior_outcomes_reviewed_before_sampling=False)
    reg=dict(version='phase2c_fixed_six_v1',seed=SEED,frame=sorted(frame,key=lambda r:int(r['team_id'])),excluded_prediction_team_ids=sorted(excluded),selected=draw(frame),sampling_implementation='random.Random(20240219).sample(numerically_sorted_stable_ID_frame,6); selected output sorted by numeric ID',sampling_code_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),dates=spec['dates'],prior_familiarity='Boston and first CLE/DEN/DET/ORL/PHI/SAS cohorts excluded. Prior transfer follow-up has inspected MEM, POR, WAS, MIN, NYK, MIL, IND, UTA, OKC, TOR and selected fixtures NYK/Randle and CHA/Ball. Earlier historical cases also include PHI/Embiid, GSW/Curry, HOU/Sengun. General NBA historical familiarity exists; eligible teams are not claimed wholly unseen. No injury information enters this draw, no redraw.',scope='development collection, not final validation; exactly6 new prediction teams, other teams only targeted actual-member followup/history',collection_spec_sha256=hashlib.sha256((json.dumps(spec,indent=2)+'\n').encode()).hexdigest())
    for name,v in [('collection_v1',spec),('sample_v1',reg)]:
        p=D/'registration'/(name+'.json');p.write_text(json.dumps(v,indent=2)+'\n');p.with_suffix('.sha256').write_text(hashlib.sha256(p.read_bytes()).hexdigest()+'\n')
    print(json.dumps(reg['selected'],indent=2))
